// ── Wizard init ───────────────────────────────────────────────────────────────
console.log('\n── Wizard init & createNewStack ───────────────────────────');
check('initWizard defined',                typeof G.initWizard==='function');
if(typeof G.initWizard==='function') G.initWizard();
check('initWizard: step=0',                G._wiz.step===0);
check('initWizard: peptides=[]',           G._wiz.peptides.length===0);
check('initWizard: goals=[]',              G._wiz.goals.length===0);
check('initWizard: cycle_length set',      G._wiz.cycle_length>0,               `got ${G._wiz.cycle_length}`);
check('initWizard: stackIndex=-1',         G._wiz.stackIndex===-1);
check('initWizard: stackName is string',   typeof G._wiz.stackName==='string'&&G._wiz.stackName.length>0);

// ── _nextStackName: new stacks bump Cycle N (not always "Cycle 1") ──
if(typeof G._nextStackName==='function'){
  var _nsSaved=G._userStacks;
  G._userStacks=[];                       check('_nextStackName: first protocol = Protocol 1', G._nextStackName()==='Protocol 1');
  G._userStacks=[{name:'Protocol 1'}];    check('_nextStackName: after Protocol 1 = Protocol 2', G._nextStackName()==='Protocol 2');
  G._userStacks=[{name:'Protocol 1'},{name:'Protocol 2'},{name:'Protocol 3'}]; check('_nextStackName: bumps to Protocol 4', G._nextStackName()==='Protocol 4');
  G._userStacks=[{name:'Protocol 1'},{name:'Protocol 3'}]; check('_nextStackName: past highest Protocol N (no collision)', G._nextStackName()==='Protocol 4');
  G._userStacks=[{name:'Cutting Stack'},{name:'Bulking'}]; check('_nextStackName: non-numbered names → next slot', G._nextStackName()==='Protocol 3');
  G._userStacks=_nsSaved;
  // initWizard uses it for a fresh (non-edit) stack
  G._userStacks=[{name:'Protocol 1'}]; G.initWizard();
  // Henrik, 2026-11-17: fun names, as in Workout ("random, so a user can never get the same name for exact the same
  // prgoram ever"): a new protocol gets '"<fun>", <N>-Week <goal>' instead of "Protocol N".
  check('initWizard: a new protocol gets a fun name, not "Protocol N"', /^".+", 12-Week Protocol$/.test(G._wiz.stackName), G._wiz.stackName);
  G._userStacks=_nsSaved;
}
if(typeof G.stackFunName==='function'){
  var _fnSaved=G._userStacks;
  check('fun name: Enhanced first in the pool', G.stackFunName('enhanced',16,0,[])==='"Better Living Through Chemistry", 16-Week Enhanced', G.stackFunName('enhanced',16,0,[]));
  check('fun name: each goal has its own pool', new Set(['enhanced','trt','muscle','recovery','skin','fat','cognitive','antiaging'].map(function(g){return G.STACK_FUN_NAMES[g][0];})).size===8);
  var _tk=[];for(var _k=0;_k<40;_k++)_tk.push(G.stackFunName('fat',12,Math.random(),_tk));
  check('fun name: 40 identical protocols never share a name', new Set(_tk.map(function(n){return n.toLowerCase();})).size===40, _tk.slice(-2).join(' | '));
  var _sn=new Set();for(var _k2=0;_k2<30;_k2++)_sn.add(G.stackFunName('skin',8,Math.random(),[]));
  check('fun name: the pick is random', _sn.size>1);
  check('goal: Enhanced compounds win', G._stackFunGoal({enhanced:{compounds:[{id:'x'}]},trt:{compounds:[{id:'t'}]},peptides:[]})==='enhanced');
  check('goal: then TRT', G._stackFunGoal({trt:{compounds:[{id:'t'}]},peptides:[]})==='trt');
  check('goal: the wizard goals count', G._stackFunGoal({goals:['fat'],peptides:[]})==='fat');
  check('goal: nothing in it is general', G._stackFunGoal({peptides:[]})==='general');
  // The wizard: the name follows the choices until typed, an edited protocol keeps its own.
  G._userStacks=[]; G.initWizard(); G._wiz.goals=['cognitive']; G._wizAutoName();
  var _n1=G._wiz.stackName; G._wizAutoName();
  check('wizard: the name follows the goal and stays put while open', /^".+", 12-Week Cognitive$/.test(_n1) && G._wiz.stackName===_n1, _n1);
  G.wizSetStackName('My Stack'); G._wizAutoName();
  check('wizard: a typed name always wins', G._wiz.stackName==='My Stack' && G._wiz.nameTyped===true);
  G._wiz={editMode:true,stackName:'Protocol 1',goals:['fat']}; G._wizAutoName();
  check('wizard: editing keeps the protocol\'s own name', G._wiz.stackName==='Protocol 1');
  // Existing protocols still called "Protocol N" are renamed once; a chosen name is left alone.
  var _st=[{name:'Protocol 1',cycle_length:12,peptides:[],enhanced:{compounds:[{id:'a'}]}},{name:'Protocol 2',cycle_length:12,peptides:[],enhanced:{compounds:[{id:'a'}]}},{name:'Cutting',peptides:[]},{name:'',cycle_length:8,peptides:[]}];
  var _chg=G._funRenameStacks(_st);
  check('rename: "Protocol N" and unnamed protocols get fun names, all different', _chg===true && /^".+", 12-Week Enhanced$/.test(_st[0].name) && /^".+", 12-Week Enhanced$/.test(_st[1].name) && _st[0].name!==_st[1].name && /^".+", 8-Week Protocol$/.test(_st[3].name), _st.map(function(x){return x.name;}).join(' | '));
  check('rename: a chosen name is left alone', _st[2].name==='Cutting');
  check('rename: a second load changes nothing', G._funRenameStacks(_st)===false);
  var _d=G.stackDetails({cycle_length:12,peptides:[{id:'a'},{id:'b'}],enhanced:{compounds:[{id:'c'}]}});
  check('details: goal, length and contents', _d==='Enhanced · 12 weeks · 2 peptides · 1 compound', _d);
  G._userStacks=_fnSaved;
}

// ── Today view: de-dupe injection slots (dose-edit doubling fix) ──
if (typeof G._dedupInjectionSlots === 'function') {
  // A slot with both an administered (logged) shot and a newly-planned one collapses
  // to ONE row, keeping the logged shot.
  var _ddOut = G._dedupInjectionSlots([
    {compound_id:'hgh', time_of_day:'AM', dose:'2', logged:true},
    {compound_id:'hgh', time_of_day:'AM', dose:'3', logged:false},
  ]);
  check('dedup slots: duplicate compound+slot collapses to one', _ddOut.length === 1);
  check('dedup slots: keeps the already-logged shot', _ddOut[0].logged === true && _ddOut[0].dose === '2');
  // AM and PM are distinct slots — both survive.
  check('dedup slots: AM and PM are independent',
    G._dedupInjectionSlots([
      {compound_id:'hgh', time_of_day:'AM', dose:'3'},
      {compound_id:'hgh', time_of_day:'PM', dose:'3'},
    ]).length === 2);
  // Different compounds in the same slot both survive; original order preserved.
  var _ddOrder = G._dedupInjectionSlots([
    {compound_id:'glow', time_of_day:'AM', dose:'0.1'},
    {compound_id:'hgh',  time_of_day:'AM', dose:'3'},
    {compound_id:'glow', time_of_day:'AM', dose:'0.1'},
  ]);
  check('dedup slots: distinct compounds kept, order preserved',
    _ddOrder.length === 2 && _ddOrder[0].compound_id === 'glow' && _ddOrder[1].compound_id === 'hgh');
  check('dedup slots: tolerates empty/null input',
    G._dedupInjectionSlots([]).length === 0 && G._dedupInjectionSlots(null).length === 0);

  // ── AN EXTRA DOSE OF THE SAME COMPOUND IS NOT A DUPLICATE ────────────────
  // Reported 2026-09-13: an extra 75 mg Nebido added by hand never appeared in Today.
  // It was logged correctly in the backend — cycle_id "manual", source "manual",
  // logged true — but the protocol's own 100 mg Nebido already held the key
  // "nebido_AM", so the manual shot was dropped. The one screen that records what
  // actually went into the user showed less than they had taken.
  //
  // These are the real rows from prod for 2026-09-13, shape and all.
  var _ddToday = [
    {compound_id:'glow',        time_of_day:'AM', dose:'0.09', logged:true,  cycle_id:'protocol_4_2026-09-11'},
    {compound_id:'hgh',         time_of_day:'AM', dose:'3',    logged:true,  cycle_id:'protocol_4_2026-09-11'},
    {compound_id:'hgh',         time_of_day:'AM', dose:'3',    logged:false, cycle_id:'protocol_4_2026-09-11'},
    {compound_id:'mast_e',      time_of_day:'AM', dose:'100',  logged:false, cycle_id:'protocol_4_2026-09-11'},
    {compound_id:'nebido',      time_of_day:'AM', dose:'100',  logged:true,  cycle_id:'protocol_4_2026-09-11'},
    {compound_id:'nebido',      time_of_day:'AM', dose:'75',   logged:true,  cycle_id:'manual', source:'manual'},
    {compound_id:'retatrutide', time_of_day:'AM', dose:'3',    logged:true,  cycle_id:'protocol_4_2026-09-11'}
  ];
  var _ddRes = G._dedupInjectionSlots(_ddToday);
  var _ddNeb = _ddRes.filter(function(e){ return e.compound_id === 'nebido'; });
  check('dedup slots: a manually-added extra dose survives alongside the protocol dose',
    _ddNeb.length === 2, _ddNeb.map(function(e){return e.dose;}).join(' + ') || 'only ' + _ddNeb.length);
  check('  …and it is the 75 mg manual one that was being eaten',
    _ddNeb.some(function(e){ return e.dose === '75' && e.cycle_id === 'manual'; }));
  // The doubling this function exists for is unchanged: same protocol, same compound,
  // same slot — one row, and it is the logged one.
  check('  …while the dose-edit doubling inside one protocol still collapses',
    _ddRes.filter(function(e){ return e.compound_id === 'hgh'; }).length === 1 &&
    _ddRes.filter(function(e){ return e.compound_id === 'hgh'; })[0].logged === true);
  check('  …so the real day renders 6 rows, not 5', _ddRes.length === 6, String(_ddRes.length));

  // THE INVARIANT HENRIK ASKED FOR: nothing taken is ever hidden.
  // A logged row is the record of something that was administered. It may only be
  // merged away by ANOTHER logged row of the same compound, slot AND origin.
  check('dedup slots: no logged dose is ever dropped for a different-origin row',
    (function(){
      var seen = {};
      _ddRes.forEach(function(e){ seen[e.compound_id+'|'+(e.time_of_day||'')+'|'+(e.cycle_id||'')] = e; });
      return _ddToday.filter(function(e){ return e.logged; }).every(function(e){
        var k = e.compound_id+'|'+(e.time_of_day||'')+'|'+(e.cycle_id||'');
        return seen[k] && seen[k].logged;
      });
    })());
  // ── TWO PROTOCOLS ON ONE SLOT IS A TRANSITION, NOT TWO INJECTIONS ────────
  // ⚠️ THESE TWO ASSERTIONS USED TO SAY THE OPPOSITE, AND THEY WERE WRONG.
  // Written 2026-09-13 alongside the cycle_id key, on the reasoning that a different
  // origin means a different administration. Reality answered on 2026-09-14: with
  // protocol_4 and protocol_5 both live, Today listed Glow twice and HGH twice in each
  // slot — 8 rows for 5 doses, and the user takes ONE of each. Overlapping protocols
  // are how a schedule is revised; the old rows linger until they are cleaned up.
  //
  // Same for a T-Calc plan beside a protocol row: T-Calc is the only thing that
  // schedules testosterone (_genInjBatches suppresses the whole TRT tier), so those two
  // rows are one planned dose under two mechanisms, never two injections.
  check('dedup slots: two protocols dosing the same compound collapse to one',
    G._dedupInjectionSlots([
      {compound_id:'nebido', time_of_day:'AM', dose:'100', cycle_id:'protocol_a'},
      {compound_id:'nebido', time_of_day:'AM', dose:'100', cycle_id:'protocol_b'}
    ]).length === 1);
  check('  …even when the revision changed the dose',
    G._dedupInjectionSlots([
      {compound_id:'hgh', time_of_day:'AM', dose:'3', cycle_id:'protocol_4'},
      {compound_id:'hgh', time_of_day:'AM', dose:'2', cycle_id:'protocol_5'}
    ]).length === 1);
  check('  …and a T-Calc plan beside a protocol row is still one dose',
    G._dedupInjectionSlots([
      {compound_id:'enanthate', time_of_day:'AM', dose:'50',  cycle_id:'protocol_9'},
      {compound_id:'enanthate', time_of_day:'AM', dose:'100', cycle_id:'tcalc'}
    ]).length === 1);

  // THE REPORTED DAY, verbatim from prod for 2026-09-14. Two protocols, 8 stored rows,
  // 5 doses to take.
  var _ovDay = [
    {compound_id:'glow',   time_of_day:'AM', dose:'0.09', logged:true,  cycle_id:'protocol_4_2026-09-11', id:'8b249b47'},
    {compound_id:'glow',   time_of_day:'AM', dose:'0.09', logged:true,  cycle_id:'protocol_5_2026-09-15', id:'c387c668'},
    {compound_id:'hgh',    time_of_day:'AM', dose:'3',    logged:true,  cycle_id:'protocol_4_2026-09-11', id:'b34b7b03'},
    {compound_id:'hgh',    time_of_day:'AM', dose:'2',    logged:true,  cycle_id:'protocol_5_2026-09-15', id:'d244e179'},
    {compound_id:'hgh',    time_of_day:'PM', dose:'3',    logged:false, cycle_id:'protocol_4_2026-09-11', id:'6584e72a'},
    {compound_id:'hgh',    time_of_day:'PM', dose:'2',    logged:false, cycle_id:'protocol_5_2026-09-15', id:'8605aabb'},
    {compound_id:'mast_e', time_of_day:null, dose:'100',  logged:false, cycle_id:'protocol_5_2026-09-15', id:'f2be2a92'},
    {compound_id:'nebido', time_of_day:'AM', dose:'100',  logged:false, cycle_id:'protocol_4_2026-09-11', id:'ca93f1b7'}
  ];
  var _ovOut = G._dedupInjectionSlots(_ovDay);
  check('dedup slots: the reported overlapping-protocol day renders 5 doses, not 8',
    _ovOut.length === 5, _ovOut.length + ': ' + _ovOut.map(function(e){return e.compound_id+'/'+(e.time_of_day||'-');}).join(' '));
  check('  …one Glow, one HGH per slot, plus Nebido and Masteron',
    _ovOut.filter(function(e){return e.compound_id==='glow';}).length === 1 &&
    _ovOut.filter(function(e){return e.compound_id==='hgh' && e.time_of_day==='AM';}).length === 1 &&
    _ovOut.filter(function(e){return e.compound_id==='hgh' && e.time_of_day==='PM';}).length === 1 &&
    _ovOut.filter(function(e){return e.compound_id==='nebido';}).length === 1 &&
    _ovOut.filter(function(e){return e.compound_id==='mast_e';}).length === 1);
  // …and the hand-added extra that started all this still survives beside the plan.
  check('  …while a hand-added extra dose is still its own row',
    G._dedupInjectionSlots([
      {compound_id:'nebido', time_of_day:'AM', dose:'100', logged:true, cycle_id:'protocol_4_2026-09-11', id:'r1'},
      {compound_id:'nebido', time_of_day:'AM', dose:'75',  logged:true, cycle_id:'manual', source:'manual', id:'r2'}
    ]).length === 2);
  check('  …and two hand-added extras are two rows, not one',
    G._dedupInjectionSlots([
      {compound_id:'nebido', time_of_day:'AM', dose:'50', logged:true, cycle_id:'manual', source:'manual', id:'m1'},
      {compound_id:'nebido', time_of_day:'AM', dose:'50', logged:true, cycle_id:'manual', source:'manual', id:'m2'}
    ]).length === 2);
}

