  check('AM/PM labels unchanged', G._slotLabel('AM')==='AM' && G._slotLabel('PM')==='PM');
  check('_slotKey maps a slot to its field suffix',
    G._slotKey('MID')==='mid' && G._slotKey('AM')==='am' && G._slotKey('PM')==='pm');
