  var _edRet=G._renderEditPep({id:'retatrutide',name:'Retatrutide',times:['AM'],days:[0],dose_am:'3',unit_am:'mg',active:true},0);
  check('non-GH compound gets no fasted hint', !_edRet.includes('(fasted)'));

