  // Today ordering puts Pre-GYM between AM and PM.
  var _doses=[{time_of_day:'PM'},{time_of_day:'MID'},{time_of_day:'AM'}];
  _doses.sort(function(a,b){return (G.TIME_RANK[a.time_of_day]??2)-(G.TIME_RANK[b.time_of_day]??2);});
